import "./Task.css";
import { useBrowser } from "../../context/browser-context";
import { Fragment, useEffect } from "react";

export const Task = () => {

  const {time, message, name, browserDispatch} = useBrowser();

  useEffect(()=> {
    getCurrentTime();
    // eslint-disable-next-line
  }, [time, message])

  const getCurrentTime = () => {
    const today = new Date();
    const hours = today.getHours();
    const minutes = today.getMinutes();

    const hour = hours < 10 ? `0${hours}`: hours; 
    const minute = minutes < 10 ? `0${minutes}` : minutes; 

    const currentTime = `${hour}:${minute}`
    //console.log(currentTime, "current time")
    setTimeout(getCurrentTime, 1000);

    browserDispatch({
      type: "TIME",
      payload: currentTime
    })

    browserDispatch({
      type: "MESSAGE",
      payload: hours
    })
  }

  const handleTaskChange = (event) => {
    if (event.key === "Enter" && event.target.value.length > 0){
        browserDispatch({
            type: "TASK",
            payload: event.target.value
        })
        localStorage.setItem("task", event.target.value);
        localStorage.setItem("date", new Date.getDate());
    }
}
  return (
    <div className="task-container d-flex direction-column align-center gap">
        <span className="time">{time}</span>
        <span className="message">{message}, {name}</span>
        <Fragment>
          <span className="focus-question">What is your main focus for today?</span>
          <form>
            <input required className="input task-input" onKeyPress={handleTaskChange} />
          </form>

        </Fragment>
    </div>

  )
}
